translation:
// Debounce utility: delays function execution until after wait milliseconds have elapsed
function debounce(fn, wait) {
  let timerId = null;
  return function(...args) {
    const context = this;
    clearTimeout(timerId);
    timerId = setTimeout(() => fn.apply(context, args), wait);
  };
}

// Example usage: avoid frequent saves while user is typing
const autosave = debounce(() => {
  console.log('Auto-saving data...');
  // perform save operation here
}, 800);

// Suppose 'inputField' is a text input element
const inputField = document.getElementById('inputField');
if (inputField) {
  inputField.addEventListener('input', autosave);
}

Chinese: Here's a JavaScript debounce utility and a short usage example:

```javascript
function debounce(fn, delay) {
  let timer = null;
  return function(...args) {
    const context = this;
    clearTimeout(timer);
    timer = setTimeout(() => {
      fn.apply(context, args);
    }, delay);
  };
}

// Example:
const onResize = debounce(() => {
  console.log('Window resized at', new Date().toISOString());
}, 300);

window.addEventListener('resize', onResize);
```

Explanation: debounce delays calling the provided function until no calls have occurred for the specified delay. It's useful for rate-limiting events like scroll, resize, or input.

