Here's a small Python function to compute Fibonacci numbers with memoization:

```python
def fibonacci(n, memo=None):
    """
    Return the nth Fibonacci number (0-indexed) using memoization.
    Example: fibonacci(0) == 0, fibonacci(1) == 1, fibonacci(6) == 8
    """
    if memo is None:
        memo = {}
    if n in memo:
        return memo[n]
    if n < 0:
        raise ValueError("n must be non-negative")
    if n <= 1:
        return n
    memo[n] = fibonacci(n - 1, memo) + fibonacci(n - 2, memo)
    return memo[n]

# Example usage:
if __name__ == "__main__":
    for i in range(10):
        print(i, fibonacci(i))
