def factorial_iterative(n):
    """Return n! using an iterative approach; raises ValueError if n<0 or not int."""
    if not isinstance(n, int) or n < 0:
        raise ValueError("n must be a non-negative integer")
    result = 1
    for i in range(2, n + 1):
        result *= i
    return result

def factorial_recursive(n):
    """Return n! using recursion."""
    if not isinstance(n, int) or n < 0:
        raise ValueError("n must be a non-negative integer")
    return 1 if n in (0, 1) else n * factorial_recursive(n - 1)

# Example usage
if __name__ == "__main__":
    print(factorial_iterative(5))  # 120
    print(factorial_recursive(6))  # 720

def fib(n, memo=None):
    if memo is None:
        memo = {}
    if n < 2:
        return n
    if n in memo:
        return memo[n]
    memo[n] = fib(n - 1, memo) + fib(n - 2, memo)
    return memo[n]

# Example: fib(10) returns 55 — uses memoization to avoid exponential recursion.

Here's a small Python script for a simple command-line todo list stored in a JSON file:

```python
import json
import sys
from pathlib import Path

DB = Path.home() / ".simple_todo.json"

def load():
    if DB.exists():
        return json.loads(DB.read_text())
    return []

def save(items):
    DB.write_text(json.dumps(items, indent=2))

def list_items(items):
    if not items:
        print("No tasks.")
        return
    for i, t in enumerate(items, 1):
        status = "[x]" if t.get("done") else "[ ]"
        print(f"{i}. {status} {t['text']}")

def add_item(items, text):
    items.append({"text": text, "done": False})
    save(items)
    print("Added.")

def remove_item(items, index):
    try:
        removed = items.pop(index-1)
        save(items)
        print(f"Removed: {removed['text']}")
    except IndexError:
        print("Invalid index.")

def toggle_item(items, index):
    try:
        items[index-1]["done"] = not items[index-1]["done"]
        save(items)
        print("Toggled.")
    except IndexError:
        print("Invalid index.")

def usage():
    print("Usage: todo.py [list|add|rm|toggle] [args]")

if __name__ == "__main__":
    items = load()
    if len(sys.argv) < 2:
        usage()
        sys.exit(1)
    cmd = sys.argv[1]
    if cmd == "list":
        list_items(items)
    elif cmd == "add" and len(sys.argv) > 2:
        add_item(items, " ".join(sys.argv[2:]))
    elif cmd == "rm" and len(sys.argv) > 2:
        remove_item(items, int(sys.argv[2]))
    elif cmd == "toggle" and len(sys.argv) > 2:
        toggle_item(items, int(sys.argv[2]))
    else:
        usage()
```

