```python
import heapq

def dijkstra(graph, start):
    """
    graph: dict where keys are node ids and values are dicts of neighbor:weight
    start: starting node id
    Returns a tuple (distances, previous) where distances[node] is shortest distance
    and previous[node] is the predecessor on the shortest path.
    """
    distances = {node: float('inf') for node in graph}
    previous = {node: None for node in graph}
    distances[start] = 0
    heap = [(0, start)]

    while heap:
        dist_u, u = heapq.heappop(heap)
        if dist_u > distances[u]:
            continue
        for v, weight in graph[u].items():
            alt = dist_u + weight
            if alt < distances[v]:
                distances[v] = alt
                previous[v] = u
                heapq.heappush(heap, (alt, v))

    return distances, previous

def reconstruct_path(previous, target):
    path = []
    node = target
    while node is not None:
        path.append(node)
        node = previous[node]
    return list(reversed(path))

# Example usage
if __name__ == "__main__":
    graph = {
        'A': {'B': 5, 'C': 1},
        'B': {'A': 5, 'C': 2, 'D': 1},
        'C': {'A': 1, 'B': 2, 'D': 4, 'E': 8},
        'D': {'B': 1, 'C': 4, 'E': 3},
        'E': {'C': 8, 'D': 3}
    }
    distances, previous = dijkstra(graph, 'A')
    print("Distances from A:", distances)
    print("Shortest path to E:", reconstruct_path(previous, 'E'))
```

