import string
import secrets

def generate_password(length=16, use_upper=True, use_lower=True, use_digits=True, use_special=True):
    chars = ''
    if use_upper:
        chars += string.ascii_uppercase
    if use_lower:
        chars += string.ascii_lowercase
    if use_digits:
        chars += string.digits
    if use_special:
        chars += '!@#$%^&*()-_=+[]{};:,.<>/?'
