English: import time
import random
import functools
import logging

def retry(max_attempts=5, base_delay=0.5, max_delay=30, jitter=0.1, exceptions=(Exception,)):
    """
    Decorator to retry a function with exponential backoff and optional jitter.
    Parameters:
      - max_attempts: total attempts before giving up
      - base_delay: initial delay in seconds
      - max_delay: cap for computed delay
      - jitter: max random jitter to add (seconds)
      - exceptions: tuple of exception classes that trigger a retry
    """
    def decorator(fn):
        @functools.wraps(fn)
        def wrapper(*args, **kwargs):
            attempt = 0
            while True:
                try:
                    return fn(*args, **kwargs)
                except exceptions as e:
                    attempt += 1
                    if attempt >= max_attempts:
                        logging.exception("Max retries reached for %s", fn.__name__)
                        raise
                    # exponential backoff
                    delay = min(base_delay * (2 ** (attempt - 1)), max_delay)
                    # optional jitter
                    if jitter:
                        delay += random.uniform(0, jitter)
                    logging.debug("Retry %d/%d for %s after %.2fs due to %s",
                                  attempt, max_attempts, fn.__name__, delay, e)
                    time.sleep(delay)
        return wrapper
    return decorator

# Example usage:
if __name__ == "__main__":
    import requests

    @retry(max_attempts=4, base_delay=1, jitter=0.5, exceptions=(requests.RequestException,))
    def fetch(url):
        resp = requests.get(url, timeout=2)
        resp.raise_for_status()
        return resp.text

    try:
        content = fetch("https://example.com")
        print("Fetched", len(content), "bytes")
    except Exception as e:
        print("Failed to fetch:", e)

