    if not data.get('text'):
        abort(400, 'Missing "text" field')
    nid = str(uuid4())
    note = {'id': nid, 'text': data['text']}
    notes[nid] = note
    return jsonify(note), 201

@app.route('/notes/<note_id>', methods=['GET'])
