    note = notes.get(note_id)
    if not note:
        abort(404)
    return jsonify(note)

@app.route('/notes/<note_id>', methods=['DELETE'])
def delete_note(note_id):
    if note_id in notes:
        del notes[note_id]
        return '', 204
    abort(404)

