def iterative_fibonacci(n):
    """Return a list of the first n Fibonacci numbers (starting with 0, 1)."""
    if n <= 0:
        return []
    if n == 1:
        return [0]
    seq = [0, 1]
    for _ in range(2, n):
        seq.append(seq[-1] + seq[-2])
