Here's a small Python script that finds the N largest files in a directory (recursively) and prints their sizes in human-readable form:

```python
import os
import heapq

def human_readable(size):
    for unit in ['B','KB','MB','GB','TB']:
        if size < 1024:
            return f"{size:.1f}{unit}"
        size /= 1024
    return f"{size:.1f}PB"

def find_largest_files(root_path, n=10):
    heap = []
    for dirpath, _, filenames in os.walk(root_path):
        for fname in filenames:
            try:
                path = os.path.join(dirpath, fname)
                size = os.path.getsize(path)
                if len(heap) < n:
                    heapq.heappush(heap, (size, path))
                else:
                    heapq.heappushpop(heap, (size, path))
            except OSError:
                continue
    largest = sorted(heap, reverse=True)
    for size, path in largest:
        print(f"{human_readable(size):>8}  {path}")

if __name__ == "__main__":
    import sys
    start = sys.argv[1] if len(sys.argv) > 1 else "."
    count = int(sys.argv[2]) if len(sys.argv) > 2 else 10
    find_largest_files(start, count)
```

