    items = load_items()
    if not items:
        print("No tasks.")
        return
    for i, it in enumerate(items, 1):
        print(f"{i}. {it['task']}")

def remove_item(index):
    items = load_items()
    if 1 <= index <= len(items):
        removed = items.pop(index-1)
        save_items(items)
        print("Removed:", removed['task'])
    else:
        print("Invalid index.")

def usage():
