Here’s a small Python utility to merge two dictionaries recursively (useful for combining nested configuration dicts):

def merge_dicts(a, b):
    """
    Return a new dict with keys from both a and b.
    If a key maps to dicts in both, merge them recursively.
    Otherwise, values from b override those from a.
    """
    result = a.copy()
    for k, v in b.items():
        if k in result and isinstance(result[k], dict) and isinstance(v, dict):
            result[k] = merge_dicts(result[k], v)
        else:
            result[k] = v
    return result

