def moving_average(data, window):
    if window <= 0:
        raise ValueError("Window must be positive")
    if not data:
        return []
    averages = []
    s = 0
    for i, val in enumerate(data):
        s += val
        if i >= window:
            s -= data[i - window]
        if i >= window - 1:
            averages.append(s / window)
    return averages

